// [MEDIUM_PRIORITY] PERFORMANCE: String Concatenation optimized
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.executionimport timber.log.Timberimport com.roshan.persona.brain.agentic.LlmCallerimport com.roshan.persona.brain.context.BrainBudgetimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.context.DeviceContextimport com.roshan.persona.brain.context.NetworkTypeimport com.roshan.persona.brain.context.PrivacySettingsimport com.roshan.persona.brain.context.ResponseLengthimport com.roshan.persona.brain.context.SessionIdimport com.roshan.persona.brain.context.ThermalStatusimport com.roshan.persona.brain.context.UserContextimport com.roshan.persona.brain.persona.Personaimport com.roshan.persona.brain.persona.ResponseStyleimport com.roshan.persona.brain.persona.Toneimport com.roshan.persona.brain.persona.Verbosityimport com.roshan.persona.brain.persona.Vocabularyimport com.roshan.persona.cognitive.model.ExecutionStatusimport com.roshan.persona.cognitive.model.SubTaskimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport kotlinx.coroutines.withContextimport kotlinx.coroutines.Dispatchersimport java.time.Instantimport java.util.Localeimport java.util.TimeZoneimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Brain-backed Agentic Executor (Phase 1 stub-removal). * * Real implementation of [AgenticExecutorInterface] that delegates sub-task * execution to Brain's agentic layer via [LlmCaller] (the same functional * interface the Brain's [com.roshan.persona.brain.agentic.AgenticExecutor] * uses for ReAct loop LLM queries). * * ## What this replaces * * The previous `StubAgenticExecutor` unconditionally returned `SUCCEEDED`, * which masked execution failures during plan execution — the cognitive * [PlanExecutorBridge] would report "all sub-tasks succeeded" even when the * LLM had no actual answer. This real implementation: * *   1. **Validates the LLM is available** — if `LlmCaller` is null (v1 *      before Module 4 wires `HybridLlmRouter`), returns `FAILED` with a *      `WARN` log. The [ReplanningEngine] will then trigger an `AskUser` *      fallback instead of falsely succeeding. *   2. **Builds a minimal BrainContext** — agentic execution requires a *      context for correlation, budget, and persona. We synthesize a *      minimal context (default persona, generous budget, online device) *      since the cognitive layer does not have the user's full context *      at plan-execution time. *   3. **Invokes the LLM** with the sub-task description as the prompt *      and translates the [Result] into an [ExecutionStatus]: *      - `Result.Success` → `SUCCEEDED` *      - `Result.Partial` → `SUCCEEDED` (partial is still progress) *      - `Result.Failure` → `FAILED` (preserves `retryable` for the critic) *   4. **Logs every step** with the sub-task ID + correlation ID for the *      audit trail. * * ## Why LlmCaller (not AgenticOrchestrator) * * `AgenticOrchestrator` is heavier (requires planner + executor + critic + * guardrails + toolRegistry + brainBus) and runs a full ReAct loop. The * cognitive layer's [SubTask] is a single discrete unit of work — a single * LLM call is the right granularity. v2+ can upgrade to AgenticOrchestrator * if a sub-task needs tool use (e.g., "research flights" needs WebSearchTool). * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§PlanExecutorBridge</a> */@Singletonclass BrainBackedAgenticExecutor @Inject constructor(    private val llmCaller: LlmCaller?,) : AgenticExecutorInterface {    override suspend fun executeSubTask(subTask: SubTask): ExecutionStatus =        withContext(Dispatchers.Default) {            val correlationId = CorrelationId.generate()            Timber.tag("NOUS.Cognitive").i(                TAG,                "Executing sub-task ${subTask.id} (${subTask.type}): " +                    "'${subTask.description.take(80)}' [cid=${correlationId.value.take(8)}]",            )            if (llmCaller == null) {                Timber.tag("NOUS.Cognitive").w(                    TAG,                    "Sub-task ${subTask.id} FAILED: no LLM wired " +                        "(Module 4 HybridLlmRouter not installed).",                )                return@withContext ExecutionStatus.FAILED            }            val context = buildMinimalContext(correlationId, subTask)            return@withContext try {                when (val result = llmCaller.invoke(subTask.description, context)) {                    is Result.Success -> {                        Timber.tag("NOUS.Cognitive").i(                            TAG,                            "Sub-task ${subTask.id} SUCCEEDED " +                                "(${result.data.length} chars, ${result.durationNanos / 1_000_000}ms).",                        )                        ExecutionStatus.SUCCEEDED                    }                    is Result.Partial -> {                        Timber.tag("NOUS.Cognitive").i(                            TAG,                            "Sub-task ${subTask.id} SUCCEEDED (partial) " +                                "(${result.data.length} chars).",                        )                        ExecutionStatus.SUCCEEDED                    }                    is Result.Failure -> {                        Timber.tag("NOUS.Cognitive").w(                            TAG,                            "Sub-task ${subTask.id} FAILED: ${result.error.message} " +                                "(retryable=${result.error.retryable}).",                        )                        ExecutionStatus.FAILED                    }                }            } catch (t: Throwable) {                Timber.tag(TAG).e("Sub-task ${subTask.id} crashed during LLM invocation.", t)                ExecutionStatus.FAILED            }        }    /**     * Build a minimal [BrainContext] suitable for a single LLM invocation.     *     * The cognitive layer does not have the full user/device/persona context     * at plan-execution time (that lives in the Brain pre-processor). We     * synthesize a minimal context with safe defaults:     *  - Default [Persona] (Jarvis).     *  - Default [UserContext] (anonymous, balanced response length).     *  - Default [DeviceContext] (no thermal throttling, online over WiFi).     *  - Generous [BrainBudget] (sub-tasks may take up to 15s, $0.50).     *     * v2+ will inject the real BrainPreProcessor so we get the actual user     * context + device state + persona — for v1 this minimal context is     * enough to drive the LLM call.     */    private fun buildMinimalContext(correlationId: CorrelationId, subTask: SubTask): BrainContext {        val now = Instant.now()        return BrainContext(            correlationId = correlationId,            sessionId = SessionId("cognitive-${subTask.id}"),            timestamp = now,            timezone = TimeZone.getDefault(),            activePersona = Persona(                id = "jarvis",                displayName = "JARVIS",                systemPromptTemplate = "You are NOUS, an on-device AI assistant.",                skillPreferences = emptyMap(),                responseStyle = ResponseStyle(                    tone = Tone.WITTY,                    verbosity = Verbosity.BALANCED,                    useEmoji = false,                    vocabulary = Vocabulary.SIMPLE,                ),            ),            userContext = UserContext(                userId = "cognitive-anonymous",                displayName = null,                preferredLanguage = Locale.getDefault(),                preferredResponseLength = ResponseLength.BALANCED,                skillPreferences = emptyMap(),                privacySettings = PrivacySettings(),                monthlyLlmBudgetUsd = 5.0f,                monthlyLlmSpentUsd = 0.0f,            ),            deviceContext = DeviceContext(                thermalStatus = ThermalStatus.NONE,                availableRamMb = 4_096,                batteryLevel = 100,                isCharging = true,                isOnline = true,                networkType = NetworkType.WIFI,                gpuAvailable = false,                gpuVramMb = 0,            ),            conversationHistory = emptyList(),            pendingExpectation = null,            ambientContext = null,            budget = BrainBudget.GENEROUS,        )    }    private companion object {        private const val TAG = "BrainBackedAgenticExec"    }}